import{_ as s,l as i,o as a,c as l,v as t,p as n,x as r,d as p,i as c,S as m}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"CompCert 与编译器正确性","description":"","frontmatter":{"title":"CompCert 与编译器正确性","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/compcert-correctness.md","filePath":"cs/compcert-correctness.md","lastUpdated":1789023840000}'),d={name:"cs/compcert-correctness.md"};function C(h,e,_,f,u,S){const o=i("Mermaid");return a(),l("div",null,[e[1]||(e[1]=t('<h1 id="compcert-与编译器正确性" tabindex="-1">CompCert 与编译器正确性 <a class="header-anchor" href="#compcert-与编译器正确性" aria-label="Permalink to &quot;CompCert 与编译器正确性&quot;">​</a></h1><div class="epigraph"><p>对 Clight 到汇编的每一遍给出证明：若源有定义行为，目标的观察与源相关。信任基是证明助手核与公理，而不是优化直觉。</p><footer>—— 据 Leroy, Formal Verification of a Realistic Compiler, 2009；对照[证明助手](/cs/proof-assistants) 与[操作语义](/cs/operational-semantics) 整理</footer></div><p>上一课<a href="/cs/dsl-embedding">DSL</a> 仍可能错降。缺口是<strong>经证明的编译</strong>：CompCert。本课钉模拟关系与「不证明 UB 源」，模糊测试下一课是另一条质量路。不重写 CIC。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>优化编译器大，测试覆盖不到全部变换。<a href="/cs/type-soundness">健全性</a> 是语言的；这里是<strong>编译器</strong>的：\\(\\mathrm{beh}(S) \\supseteq \\mathrm{beh}(C(S))\\) 一类（具体陈述看论文：未定义可更任意）。缺口是<strong>逐遍证明</strong>，不是 lex。</p><p>CompCert 不覆盖全部 GCC 优化，换保证。</p><h3 id="正确性不是「生成代码很快」" tabindex="-1">正确性不是「生成代码很快」 <a class="header-anchor" href="#正确性不是「生成代码很快」" aria-label="Permalink to &quot;正确性不是「生成代码很快」&quot;">​</a></h3><p>性能另测。证明保证语义，不保证最优寄存器分配。</p><p><span class="marginnote">Leroy 2009 CACM/POPL 系列。Coq。本课不列全部中间语言名。与 UB 课：源 UB 则定理不约束。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每遍：小步或大步语义 + 向前/向后模拟。组合。抽取 OCaml 编译器。信任：Coq 核、反汇编器、ABI 公理。</p>',11)),(a(),n(m,null,{default:r(()=>[c(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20SRC%5B%22Clight%22%5D%20--%3E%20P1%5B%22%E5%B7%B2%E8%AF%81%E9%81%8D%22%5D%0A%20%20P1%20--%3E%20ASM%5B%22%E6%B1%87%E7%BC%96%22%5D%0A%20%20SRC%20--%3E%20SIM%5B%22%E6%A8%A1%E6%8B%9F%E5%85%B3%E7%B3%BB%22%5D%0A%20%20ASM%20--%3E%20SIM%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[p(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p>与<a href="/cs/ssa-form">SSA</a>：CompCert 有自己的 SSA 与证明负担。工业 LLVM 用测试+fuzz，少全证。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>未模型化的 IO、内联汇编、并发（早期）在保证外。不要把 CompCert 当 C++ 全语言。链接：分离编译有后续工作，点名。</p><p>抽取代码仍要 OCaml 运行时——信任基。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 Csmith。后课默认：现实编译器可形式化子集。下一课编译器模糊测试 Csmith。</p><p>也不把 CompCert 当电子设计自动化。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CompCert：逐遍模拟，定义行为被保留。</li><li>UB 源不在定理内；优化范围小于 GCC。</li><li>信任基是助手核与公理。</li><li>出处：Leroy, 2009；对照 Wright–Felleisen、Coq。</li></ul>',9))])}const b=s(d,[["render",C]]);export{A as __pageData,b as default};
